		c.JSON(http.StatusBadRequest, problemDetail)
		return
	}
	if err != nil {
		logger.DataRepoLog.Errorf("Invalid regular expression: %s", err)
	}

	s.Processor().CreateEeGroupSubscriptionsProcedure(c, ueGroupId, eeSubscription)
